-- Divinus — aprofundamento de cada mensagem do hero (Leitura Dinâmica da Bíblia)

alter table public.hero_messages add column slug text;
alter table public.hero_messages add column reference text;
alter table public.hero_messages add column contexto text;
alter table public.hero_messages add column capitulo text;
alter table public.hero_messages add column aplicacao text;
alter table public.hero_messages add column conexao text;

update public.hero_messages set slug = 'criacao-da-luz', reference = 'Gênesis 1', contexto = 'Gênesis abre o livro sem autor humano identificado no texto, compilado ao longo de gerações e atribuído tradicionalmente a Moisés. É o pano de fundo de tudo que vem depois: como o mundo e as pessoas existem.', capitulo = 'Deus cria em etapas, nomeando e separando — luz e trevas, água e terra, dia e noite. Cada etapa termina com a mesma avaliação: "e viu Deus que era bom". A criação é um processo, não um evento instantâneo perfeito de uma vez.', aplicacao = 'Se até a luz precisou ser separada da escuridão, sua clareza também vai vir por etapas. Você não precisa ter tudo resolvido hoje — precisa dar o próximo passo de separação entre o que é caos e o que é ordem na sua vida.', conexao = 'A mesma ideia de "formar ordem a partir do caos" reaparece em Isaías 45:7, e depois em João 1, onde a luz volta como imagem central — agora como uma pessoa.' where sort_order = 0;
update public.hero_messages set slug = 'deus-viu-que-era-bom', reference = 'Gênesis 1:31', contexto = 'Este versículo fecha os seis dias da criação, antes do descanso do sétimo dia. É o único momento em que o texto usa "muito bom" em vez de apenas "bom".', capitulo = 'Cada etapa da criação recebeu uma avaliação boa isoladamente. Só ao ver o conjunto completo — luz, terra, mar, plantas, animais, pessoas — Deus chama de muito bom. O valor de uma parte às vezes só aparece no todo.', aplicacao = 'Talvez você esteja avaliando um dia ruim, uma fase difícil, isoladamente. Dê um passo atrás: como essa parte se encaixa no conjunto da sua história?', conexao = 'Romanos 8:28 retoma essa ideia de conjunto: todas as coisas cooperando para o bem, não cada peça sozinha.' where sort_order = 1;
update public.hero_messages set slug = 'onde-voce-esta', reference = 'Gênesis 3:9', contexto = 'É a primeira pergunta que Deus faz a um ser humano na Bíblia, logo depois de Adão e Eva comerem do fruto proibido e se esconderem entre as árvores.', capitulo = 'Deus já sabia onde eles estavam fisicamente. A pergunta não busca informação, busca abrir uma conversa que a vergonha tinha fechado. Antes de qualquer julgamento no capítulo, vem essa busca.', aplicacao = 'Quando você erra e some — de Deus, de alguém, de si mesmo — a primeira resposta disponível não é acusação. É a pergunta "onde você está", feita por alguém que já sabe a resposta e quer que você volte a falar.', conexao = 'A mesma dinâmica de busca antes de qualquer coisa aparece na parábola do filho pródigo, em Lucas 15.' where sort_order = 2;
update public.hero_messages set slug = 'caim-e-abel', reference = 'Gênesis 4', contexto = 'Caim e Abel são os primeiros filhos registrados de Adão e Eva — o texto os apresenta logo depois da expulsão do Éden, já numa realidade de trabalho e oferendas.', capitulo = 'Deus aceita a oferta de Abel e não a de Caim. Antes de qualquer consequência, Deus fala diretamente com Caim: "por que você está irritado? [...] o pecado está à porta, e é a você que ele deseja, mas você deve dominá-lo". A escolha ainda estava aberta.', aplicacao = 'Raiva não é o problema — o que você faz com ela nos minutos seguintes é. Antes de agir, existe sempre uma porta em que dá pra escolher dominar em vez de ser dominado.', conexao = 'Tiago 1:19-20 desenvolve a mesma ideia: seja pronto para ouvir, tardio para falar, tardio para se irar.' where sort_order = 3;
update public.hero_messages set slug = 'noe-construiu-antes-da-chuva', reference = 'Gênesis 6-7', contexto = 'Noé é apresentado como "justo e íntegro entre os de sua geração", numa época descrita como cheia de violência e corrupção. A construção da arca levou décadas segundo a tradição.', capitulo = 'Deus dá instruções extremamente específicas de medidas e materiais. Noé constrói sem nenhuma chuva à vista, só obedecendo. O texto repete: "Noé fez tudo exatamente como Deus lhe tinha ordenado".', aplicacao = 'Existem instruções que só fazem sentido depois que a circunstância chega. Obedecer antes de entender o motivo completo é o que separa preparo de arrependimento tardio.', conexao = 'Hebreus 11:7 cita Noé como exemplo de fé exatamente por isso: ele agiu "advertido a respeito de coisas que ainda não se viam".' where sort_order = 4;
update public.hero_messages set slug = 'arco-iris-promessa', reference = 'Gênesis 9:12-16', contexto = 'Logo depois do dilúvio, Deus estabelece uma aliança com Noé e com "toda carne" — não uma aliança condicionada a comportamento futuro, mas uma promessa unilateral.', capitulo = 'O arco-íris é descrito como sinal voltado tanto para as pessoas quanto para o próprio Deus se lembrar: "verei o arco e me lembrarei da aliança eterna". O sinal existe pra ser visto depois da tempestade, não durante.', aplicacao = 'Se você está no meio da tempestade agora, o sinal ainda não apareceu — e está tudo bem. Ele normalmente vem depois, não durante, como confirmação de que passou.', conexao = 'Apocalipse 4:3 retoma a imagem do arco-íris ao redor do trono, como lembrete permanente da mesma promessa.' where sort_order = 5;
update public.hero_messages set slug = 'torre-de-babel', reference = 'Gênesis 11:1-9', contexto = 'Depois do dilúvio, a humanidade ainda fala uma única língua e se estabelece na planície de Sinar, decidindo construir uma cidade e uma torre "para não sermos espalhados".', capitulo = 'O motivo declarado não é adoração — é fazer um nome para si e resistir à instrução original de se espalhar e povoar a terra. Deus confunde as línguas exatamente no ponto em que a unidade servia a um propósito errado.', aplicacao = 'Nem toda união é saudável. Às vezes um grupo inteiro concorda porque está construindo a mesma coisa errada junto — e discordância ali seria mais saudável que consenso.', conexao = 'Atos 2 inverte a cena: no Pentecostes, línguas diferentes se entendem de novo, mas dessa vez a construção é comunidade, não um monumento a si mesmo.' where sort_order = 6;
update public.hero_messages set slug = 'abraao-saiu-sem-saber', reference = 'Gênesis 12:1-4', contexto = 'Abraão (ainda chamado Abrão) vivia em Ur dos Caldeus, numa cultura politeísta estabelecida, quando recebe o chamado para deixar terra, parentela e casa paterna.', capitulo = 'A instrução vem antes do destino: "vai [...] para a terra que eu te mostrarei". Abraão parte aos 75 anos, sem mapa, só com a promessa de que seria abençoado e se tornaria uma grande nação.', aplicacao = 'Você não precisa do itinerário completo pra dar o primeiro passo — só precisa confiar em quem está chamando o suficiente pra sair do lugar onde está parado.', conexao = 'Hebreus 11:8 descreve exatamente isso: Abraão saiu "sem saber para onde ia".' where sort_order = 7;
update public.hero_messages set slug = 'sara-riu-da-promessa', reference = 'Gênesis 18:1-15', contexto = 'Abraão tinha 99 anos e Sara cerca de 90 quando três visitantes anunciam que ela teria um filho dentro de um ano — décadas depois da promessa original.', capitulo = 'Sara ri escondida atrás da tenda, achando implausível depois de tantos anos de espera. Quando é confrontada, nega ter rido, com medo. Mesmo assim, a promessa se cumpre exatamente como dita.', aplicacao = 'Rir de descrença diante de uma promessa demorada é humano, não é o fim dela. O cumprimento não depende da sua reação, depende de quem prometeu.', conexao = 'Romanos 4:19-21 volta a essa cena para descrever fé: Abraão "não vacilou" mesmo sabendo que os corpos já não geravam vida.' where sort_order = 8;
update public.hero_messages set slug = 'agar-vista-no-deserto', reference = 'Gênesis 16 e 21', contexto = 'Agar era escrava egípcia de Sara, usada para gerar um herdeiro e depois expulsa duas vezes para o deserto — primeiro grávida, depois com o filho pequeno.', capitulo = 'Nas duas vezes, Deus a encontra sozinha no deserto, chama seu nome, e ela responde nomeando Deus de volta: "Tu és o Deus que me vê". É a única pessoa na Bíblia que dá um nome a Deus.', aplicacao = 'Ser esquecida ou descartada por pessoas não significa ser invisível de verdade. A presença que importa mais te encontra justamente onde ninguém mais está procurando.', conexao = 'Salmos 34:18 ecoa a mesma proximidade: "Perto está o Senhor dos que têm o coração quebrantado".' where sort_order = 9;
update public.hero_messages set slug = 'abraao-e-isaque-no-monte', reference = 'Gênesis 22:1-14', contexto = 'Anos depois de Isaque nascer — o filho da promessa, esperado por décadas — Deus pede a Abraão que o ofereça em sacrifício no monte Moriá, um teste extremo de confiança.', capitulo = 'Abraão obedece sem argumentar, dizendo ao servo que ele e o filho voltariam os dois. No último instante, um anjo interrompe e um carneiro aparece preso por perto — provisão que só existia porque Abraão chegou até ali confiando.', aplicacao = 'Às vezes a provisão só aparece no ponto mais tenso da obediência, não antes. Isso não é crueldade — é o momento em que fica claro que a confiança era real.', conexao = 'Tiago 2:21-22 usa esse episódio pra mostrar que fé genuína se completa em ação, não fica só na intenção.' where sort_order = 10;
update public.hero_messages set slug = 'jaco-luta-a-noite-inteira', reference = 'Gênesis 27 e 32', contexto = 'Jacó tinha enganado o irmão Esaú duas vezes — roubando a primogenitura e a bênção do pai — e passou anos fugindo. No caminho de volta, sozinho, uma figura luta com ele a noite inteira.', capitulo = 'Jacó não desiste da luta mesmo ferido no quadril, e pede uma bênção antes de soltar. Ele sai mancando, mas com um novo nome: Israel, "aquele que luta com Deus".', aplicacao = 'Algumas mudanças de identidade só acontecem depois de uma luta que te machuca. Sair mancando não é perder — é carregar a marca de ter enfrentado o que precisava enfrentar.', conexao = '2 Coríntios 12:9 descreve o mesmo padrão: força que se aperfeiçoa na fraqueza, não na ausência dela.' where sort_order = 11;
update public.hero_messages set slug = 'jose-vendido-pelos-irmaos', reference = 'Gênesis 37 e 45', contexto = 'José era o filho favorito de Jacó, alvo de inveja dos irmãos mais velhos, que o venderam como escravo para o Egito e mentiram ao pai dizendo que ele tinha morrido.', capitulo = 'Anos depois, já governador do Egito, José se revela aos irmãos que vieram pedir comida durante uma fome. Em vez de vingança, ele chora e diz: "vocês planejaram o mal contra mim, mas Deus o tornou em bem".', aplicacao = 'Guardar a história completa — não só a parte da traição — é o que permite responder com algo diferente de amargura quando a virada chega.', conexao = 'Romanos 8:28 nomeia esse mesmo princípio de forma mais ampla: tudo cooperando para o bem de quem confia.' where sort_order = 12;
update public.hero_messages set slug = 'jose-interpreta-sonhos', reference = 'Gênesis 41', contexto = 'José estava preso injustamente no Egito quando é chamado às pressas para interpretar os sonhos do Faraó, depois de dois anos esquecido na cadeia.', capitulo = 'José interpreta os sonhos como sete anos de fartura seguidos de sete de fome, e propõe um plano de armazenamento. O Faraó — que não adorava o Deus de José — reconhece nele "o espírito dos deuses" e o coloca no comando.', aplicacao = 'Seu dom pode ser reconhecido por gente que nem compartilha sua fé. Isso não invalida o dom — mostra o alcance dele.', conexao = 'Daniel 2 repete quase a mesma cena séculos depois, com outro rei estrangeiro e outro sonho decifrado.' where sort_order = 13;
update public.hero_messages set slug = 'jose-perdoa-de-verdade', reference = 'Gênesis 50:15-21', contexto = 'Depois da morte do pai Jacó, os irmãos de José temem que ele finalmente se vingue, agora que não há mais ninguém para conter sua raiva.', capitulo = 'José chora ao ouvir o medo deles e responde com a mesma frase de anos antes: o mal que planejaram, Deus tornou em bem, "para preservar a vida de muita gente". Ele os tranquiliza e continua sustentando a família.', aplicacao = 'Perdão real se prova não no momento da reconciliação inicial, mas anos depois, quando a pessoa continua escolhendo não cobrar a dívida antiga.', conexao = 'Mateus 18:21-22 traz a pergunta de Pedro sobre quantas vezes perdoar — e a resposta de Jesus sobre perdão sem limite.' where sort_order = 14;
update public.hero_messages set slug = 'sarca-ardente', reference = 'Êxodo 3', contexto = 'Moisés vivia exilado no deserto de Midiã havia 40 anos, cuidando de ovelhas, depois de fugir do Egito por matar um capataz egípcio. Era um pastor comum num dia comum.', capitulo = 'Deus aparece numa sarça que queima sem se consumir, chama Moisés pelo nome duas vezes e o convoca para libertar o povo de Israel. Moisés hesita, questiona sua própria capacidade — e mesmo assim recebe a missão.', aplicacao = 'Chamados importantes raramente chegam num templo. Chegam no meio da rotina, quando você menos espera algo mudar de direção.', conexao = '1 Coríntios 1:27 descreve o mesmo padrão: Deus escolhe as coisas fracas do mundo para envergonhar as fortes.' where sort_order = 15;
update public.hero_messages set slug = 'moises-nao-sabia-falar', reference = 'Êxodo 4:10-16', contexto = 'Depois do chamado na sarça, Moisés continua resistindo, alegando ser "pesado de boca e língua" — provavelmente algum tipo de dificuldade de fala.', capitulo = 'Em vez de forçar Moisés a superar sozinho, Deus designa Aarão, seu irmão, para falar por ele. A missão continua sendo de Moisés, mas ele não precisa carregá-la sozinho no ponto mais fraco.', aplicacao = 'Reconhecer uma limitação não cancela o chamado — só muda como ele vai ser cumprido. Pedir ajuda no seu ponto fraco é estratégia, não fracasso.', conexao = '2 Coríntios 12:9 traz a mesma lógica: "minha graça te basta, porque o meu poder se aperfeiçoa na fraqueza".' where sort_order = 16;
update public.hero_messages set slug = 'farao-disse-nao-sete-vezes', reference = 'Êxodo 7-12', contexto = 'Deus envia dez pragas sucessivas sobre o Egito para forçar a libertação dos hebreus escravizados havia gerações, cada uma mais severa que a anterior.', capitulo = 'A cada praga, o Faraó parece ceder e depois volta atrás assim que o alívio chega. Só a décima praga — a mais grave — quebra a resistência de forma definitiva.', aplicacao = 'Algumas libertações não vêm na primeira nem na quinta tentativa. Isso não significa que não vão vir — significa que a resistência que você enfrenta também é real.', conexao = 'Gálatas 6:9 fala diretamente disso: não desanimar de fazer o bem, porque no tempo certo se colhe, se não desistirmos.' where sort_order = 17;
update public.hero_messages set slug = 'mar-vermelho-passo-primeiro', reference = 'Êxodo 14', contexto = 'O povo de Israel está encurralado entre o mar e o exército egípcio perseguindo-os, em pânico, culpando Moisés por tê-los tirado do Egito para morrer no deserto.', capitulo = 'Moisés estende a mão sobre o mar e ele começa a se abrir — mas o texto deixa claro que o povo precisou caminhar por dentro do caminho seco enquanto a água ainda estava se afastando dos dois lados.', aplicacao = 'Fé раramente é esperar a situação ficar totalmente segura antes de agir. É dar o passo enquanto ainda dá pra ver risco dos dois lados.', conexao = 'Josué 3 repete a mesma dinâmica no rio Jordão: os sacerdotes entram na água antes dela parar de correr.' where sort_order = 18;
update public.hero_messages set slug = 'mana-todo-dia', reference = 'Êxodo 16', contexto = 'Depois de atravessar o mar, o povo reclama de fome no deserto. Deus responde fazendo chover pão do céu todas as manhãs, com uma instrução específica sobre quantidade.', capitulo = 'Cada família devia colher só o suficiente para aquele dia — guardar demais fazia o maná apodrecer e criar vermes, exceto na véspera do sábado. A provisão diária ensinava dependência renovada, não acúmulo.', aplicacao = 'Ansiedade sobre o futuro muitas vezes é tentar guardar maná de amanhã hoje. A provisão para amanhã chega amanhã, não antes.', conexao = 'Mateus 6:11 e 6:34 seguem a mesma lógica: pão de cada dia, sem se preocupar com o dia seguinte.' where sort_order = 19;
update public.hero_messages set slug = 'povo-reclamou-logo-depois', reference = 'Êxodo 15:22-27', contexto = 'Três dias depois de ver o mar se abrir diante deles — um dos maiores milagres já registrados — o povo chega a Mara e encontra água amarga demais para beber.', capitulo = 'Em vez de lembrar o mar aberto, o povo murmura contra Moisés imediatamente. Deus mostra a Moisés uma árvore que, jogada na água, a torna doce — e usa o momento para estabelecer um princípio de cuidado contínuo.', aplicacao = 'Ver um milagre não vacina contra a próxima queixa. Memória de fé precisa ser cultivada de propósito, ela não fica automaticamente ativa.', conexao = 'Salmos 78 é um poema inteiro sobre esse padrão de esquecimento repetido do povo — e da paciência repetida de Deus.' where sort_order = 20;
update public.hero_messages set slug = 'dez-mandamentos-depois-da-liberdade', reference = 'Êxodo 20', contexto = 'Os dez mandamentos são dados no monte Sinai depois da travessia do mar, depois do maná, depois da água da rocha — o povo já estava livre havia meses quando a lei chega.', capitulo = 'O próprio texto começa lembrando isso: "Eu sou o Senhor teu Deus, que te tirei da terra do Egito, da casa da escravidão". A identidade de povo livre vem antes de qualquer mandamento.', aplicacao = 'Regra que vem antes da identidade vira peso. Regra que vem depois da identidade vira proteção de algo que você já tem.', conexao = 'Gálatas 5:1 retoma isso no Novo Testamento: "Foi para a liberdade que Cristo nos libertou", antes de qualquer instrução de como viver essa liberdade.' where sort_order = 21;
update public.hero_messages set slug = 'bezerro-de-ouro', reference = 'Êxodo 32', contexto = 'Enquanto Moisés está no monte recebendo as tábuas da lei, o povo, impaciente com sua demora, pede a Arão que faça um deus visível — e ele funde as joias num bezerro de ouro.', capitulo = 'O povo diz sobre o bezerro: "este é o teu deus, ó Israel, que te tirou da terra do Egito" — atribuindo a um objeto recém-criado o que Deus tinha acabado de fazer. Moisés desce, vê a festa, e quebra as tábuas de tanta indignação.', aplicacao = 'Impaciência tende a preencher o vazio com qualquer coisa visível e imediata, mesmo que isso signifique trocar algo real por algo inventado na pressa.', conexao = 'Habacuque 2:18-19 questiona diretamente o valor de qualquer deus feito por mãos humanas, ídolo mudo que nada pode responder.' where sort_order = 22;
update public.hero_messages set slug = 'moises-viu-as-costas-de-deus', reference = 'Êxodo 33:18-23', contexto = 'Depois do episódio do bezerro de ouro, Moisés pede para ver a glória de Deus diretamente — um pedido de intimidade total depois de uma crise de confiança do povo.', capitulo = 'Deus responde que nenhum ser humano pode ver Seu rosto e viver, mas o coloca numa fenda da rocha e passa por ali, deixando Moisés ver apenas Suas costas depois de passar.', aplicacao = 'Nem todo pedido sincero recebe a resposta completa que você imaginou — às vezes recebe o suficiente para continuar confiando, não para entender tudo.', conexao = '1 Coríntios 13:12 traz a mesma tensão mais tarde: "agora vemos como em espelho, obscuramente".' where sort_order = 23;
update public.hero_messages set slug = 'geracao-que-nao-viu-a-promessa', reference = 'Números 14 e Deuteronômio 34', contexto = 'Depois de sair do Egito, a geração adulta que duvidou do relato dos espias sobre a terra prometida foi condenada a morrer no deserto ao longo de 40 anos, sem entrar na terra.', capitulo = 'O próprio Moisés, que liderou toda a travessia, vê a terra prometida do alto do monte Nebo mas morre sem pisar nela — a entrada coube à geração seguinte, liderada por Josué.', aplicacao = 'Nem todo trabalho que você faz vai gerar fruto que você mesmo vai colher inteiro. Isso não invalida o trabalho — só muda quem recebe a colheita.', conexao = 'João 4:37-38 fala diretamente disso: um semeia, outro colhe, e os dois se alegram juntos.' where sort_order = 24;
update public.hero_messages set slug = 'jerico-silencio-antes-da-vitoria', reference = 'Josué 6', contexto = 'Jericó era a primeira cidade fortificada que Israel precisava conquistar ao entrar na terra prometida, com muros altos e bem defendidos.', capitulo = 'A instrução de Deus foi andar em silêncio ao redor da cidade uma vez por dia durante seis dias, e sete vezes no sétimo dia, só então gritando e tocando trombetas. Nenhuma arma convencional foi usada.', aplicacao = 'Algumas vitórias pedem obediência que não faz sentido tático nenhum antes de acontecer. O silêncio disciplinado às vezes é a própria estratégia.', conexao = '2 Coríntios 10:4 descreve armas "não carnais" que têm poder de derrubar fortalezas — a mesma lógica, séculos depois.' where sort_order = 25;
update public.hero_messages set slug = 'gideao-pediu-dois-sinais', reference = 'Juízes 6', contexto = 'Gideão é encontrado escondido, debulhando trigo num lagar para escapar dos midianitas, quando um anjo o chama de "homem valente" — o oposto do que ele sentia ser.', capitulo = 'Gideão pede não um, mas dois sinais confirmando o chamado — um velo de lã molhado com o chão seco, depois o inverso. Deus atende as duas vezes, sem repreendê-lo pela insegurança.', aplicacao = 'Pedir confirmação não é falta de fé, é parte do processo de construir confiança suficiente para agir. Deus responde a dúvida sincera, não só a certeza pronta.', conexao = 'Marcos 9:24 traz a mesma honestidade: "eu creio, ajuda a minha incredulidade".' where sort_order = 26;
update public.hero_messages set slug = 'exercito-reduzido-a-trezentos', reference = 'Juízes 7', contexto = 'Gideão reúne 32 mil homens para enfrentar os midianitas, um exército muito maior. Deus instrui reduzir o número — primeiro para 10 mil, depois para apenas 300.', capitulo = 'O critério de seleção final foi como cada homem bebia água num riacho — um detalhe aparentemente pequeno decidindo quem ficava. Com apenas 300, a vitória vem de um jeito que ninguém poderia atribuir à força do exército.', aplicacao = 'Quando os recursos parecem insuficientes demais para explicar um resultado bom, geralmente é porque o resultado não devia mesmo ser explicado pelos recursos.', conexao = '1 Coríntios 1:27 fecha essa ideia: Deus escolhe o fraco para envergonhar o forte, para que ninguém se glorie diante Dele.' where sort_order = 27;
update public.hero_messages set slug = 'sansao-forca-sem-dominio', reference = 'Juízes 13-16', contexto = 'Sansão nasceu sob voto nazireu, com força sobrenatural ligada a esse compromisso, chamado para libertar Israel dos filisteus — mas viveu cedendo repetidamente a impulsos pessoais.', capitulo = 'Cada quebra de compromisso de Sansão — o cabelo, os votos, as escolhas — corrói o que sustentava sua força, até Dalila descobrir o segredo e ele perder tudo, incluindo a visão.', aplicacao = 'Dom e caráter são coisas diferentes. Ter uma capacidade extraordinária não substitui a disciplina de proteger o que sustenta essa capacidade.', conexao = 'Gálatas 5:22-23 lista domínio próprio como fruto do Espírito — não um talento à parte, mas algo que se cultiva.' where sort_order = 28;
update public.hero_messages set slug = 'rute-escolheu-ficar', reference = 'Rute 1', contexto = 'Rute era moabita, viúva, sem filhos, quando sua sogra Noemi decide voltar para Belém depois de perder marido e filhos. Noemi insiste para as noras voltarem para suas próprias famílias.', capitulo = 'Rute recusa, dizendo a frase que se tornou símbolo de lealdade: "aonde fores, irei [...] o teu povo será o meu povo, e o teu Deus, o meu Deus". Ela escolhe incerteza e estranheza cultural em vez de segurança conhecida.', aplicacao = 'Algumas das decisões mais importantes da vida não têm garantia nenhuma no momento em que são tomadas — só lealdade ao que parece certo.', conexao = 'Rute se torna bisavó de Davi, e está na genealogia de Jesus em Mateus 1 — uma estrangeira no centro da história.' where sort_order = 29;
update public.hero_messages set slug = 'ana-orou-em-silencio', reference = '1 Samuel 1', contexto = 'Ana era estéril, provocada anos a fio pela outra esposa do marido, num tempo em que ter filhos era central ao valor social de uma mulher. Ela ora no templo com tanta angústia que move os lábios sem emitir som.', capitulo = 'O sacerdote Eli a confunde com uma mulher bêbada por causa disso. Ana explica que estava derramando sua alma diante de Deus, e Eli a abençoa. Pouco depois ela engravida de Samuel, que dedica a Deus como prometeu.', aplicacao = 'Dor que não faz barulho ainda é dor real, e oração silenciosa ainda é oração completa — mesmo quando quem está por perto não entende o que está vendo.', conexao = 'Romanos 8:26 fala do Espírito intercedendo com "gemidos inexprimíveis" quando não sabemos nem como orar.' where sort_order = 30;
update public.hero_messages set slug = 'davi-o-esquecido-escolhido', reference = '1 Samuel 16', contexto = 'Deus manda o profeta Samuel ungir um novo rei entre os filhos de Jessé. Sete irmãos mais velhos desfilam diante de Samuel, e nenhum é o escolhido — Davi, o mais novo, nem tinha sido chamado, estava cuidando das ovelhas.', capitulo = 'Samuel quase escolhe pela aparência do irmão mais velho, mas Deus interrompe: "o homem vê o que está diante dos olhos, mas o Senhor vê o coração". Só depois de todos os outros passarem é que perguntam por Davi.', aplicacao = 'Ser deixado de fora da primeira lista não significa estar fora dos planos. Às vezes você é literalmente a última pessoa que chamam pra sala — e ainda assim a escolhida.', conexao = '1 Coríntios 1:28 repete o padrão: Deus escolhe as coisas desprezadas do mundo, as que não são, para reduzir a nada as que são.' where sort_order = 31;
update public.hero_messages set slug = 'davi-golias-preparo-invisivel', reference = '1 Samuel 17', contexto = 'Golias desafiava o exército de Israel havia 40 dias sem que ninguém aceitasse o duelo. Davi, ainda jovem, chega ao acampamento levando comida aos irmãos e ouve o desafio.', capitulo = 'Antes do duelo, Davi conta ao rei Saul que já matou leão e urso protegendo o rebanho — experiência que ninguém tinha visto. Ele recusa a armadura de Saul, pesada demais, e vai com a funda que já sabia usar.', aplicacao = 'O preparo que ninguém testemunhou muitas vezes é exatamente o que te qualifica para o momento que todo mundo está vendo agora.', conexao = 'Lucas 16:10 traz o princípio geral: quem é fiel no pouco também é fiel no muito.' where sort_order = 32;
update public.hero_messages set slug = 'davi-poupou-saul', reference = '1 Samuel 24', contexto = 'Saul perseguia Davi por ciúme e insegurança, mesmo depois de Davi ter servido fielmente na corte. Numa caverna, Davi encontra Saul sozinho e vulnerável, e seus homens o incentivam a matá-lo.', capitulo = 'Davi corta apenas uma borda do manto de Saul, escondido, e depois se sente mal até por isso, dizendo que não tocaria no "ungido do Senhor". Ele deixa Saul viver, mesmo tendo motivo e oportunidade de vingança.', aplicacao = 'Ter o poder de revidar e escolher não usar diz mais sobre o caráter de alguém do que qualquer vitória conquistada pela força.', conexao = 'Romanos 12:19 dá a mesma instrução: não vingar por si mesmo, deixando espaço para a justiça de Deus agir.' where sort_order = 33;
update public.hero_messages set slug = 'davi-confrontado-por-natan', reference = '2 Samuel 11-12', contexto = 'Davi, já rei, comete adultério com Bate-Seba e manda matar o marido dela, Urias, para encobrir a gravidez. O profeta Natã é enviado para confrontá-lo com uma parábola sobre um homem rico que rouba a única ovelha de um pobre.', capitulo = 'Quando Davi se indigna com a injustiça da história, Natã responde: "tu és este homem". Davi não se defende, não justifica — só responde: "pequei contra o Senhor".', aplicacao = 'Recomeço de verdade não começa com explicação nem com defesa. Começa com admitir sem rodeio o que foi feito.', conexao = 'Salmos 51 é a oração que Davi escreveu depois desse confronto — um dos textos mais crus de arrependimento da Bíblia.' where sort_order = 34;
update public.hero_messages set slug = 'salomao-pediu-sabedoria', reference = '1 Reis 3', contexto = 'Salomão se torna rei jovem, sucedendo Davi, num reino recém-consolidado. Deus aparece em sonho e pergunta o que ele quer receber.', capitulo = 'Em vez de riqueza, longevidade ou vitória sobre inimigos, Salomão pede um "coração entendido" para governar e discernir entre o bem e o mal. Deus concede isso, e acrescenta riqueza e honra por causa do pedido.', aplicacao = 'O que você pede primeiro, quando tem carta branca, revela mais sobre você do que qualquer conquista que já teve.', conexao = 'Tiago 1:5 estende esse convite a todos: "se algum de vós tem falta de sabedoria, peça a Deus".' where sort_order = 35;
update public.hero_messages set slug = 'elias-fugiu-depois-de-vencer', reference = '1 Reis 18-19', contexto = 'Elias acabou de vencer publicamente 450 profetas de Baal no monte Carmelo, num confronto espetacular que provou o poder de Deus diante de todo o povo.', capitulo = 'Logo depois, ao saber que a rainha Jezabel jurou matá-lo, Elias foge para o deserto e pede para morrer, exausto. Ele passa da maior vitória pública para o colapso emocional em questão de horas.', aplicacao = 'Vitória grande não imuniza contra queda emocional depois. O corpo e a mente cobram a conta do esforço, mesmo quando o resultado foi bom.', conexao = 'Gálatas 6:9 lembra que não se deve desanimar de fazer o bem — reconhecendo que o cansaço é parte real do caminho.' where sort_order = 36;
update public.hero_messages set slug = 'elias-comida-sono-pergunta', reference = '1 Reis 19:1-8', contexto = 'Depois de fugir exausto e pedir para morrer debaixo de uma árvore, Elias adormece. Um anjo o toca duas vezes.', capitulo = 'A primeira resposta de Deus à crise de Elias não é um discurso, é comida, água e mais sono. Só depois de descansado é que ele caminha 40 dias até o monte Horebe para o encontro decisivo.', aplicacao = 'Nem toda crise espiritual precisa de solução espiritual imediata. Às vezes a primeira coisa que falta é descanso básico do corpo.', conexao = 'Marcos 6:31 mostra Jesus fazendo o mesmo com os discípulos exaustos: "vinde [...] descansai um pouco".' where sort_order = 37;
update public.hero_messages set slug = 'deus-no-sussurro', reference = '1 Reis 19:9-13', contexto = 'No monte Horebe, Elias espera um encontro com Deus e passa por um vento forte, um terremoto e um fogo — nenhum dos três continha a presença de Deus.', capitulo = 'Depois do fogo, vem "uma voz mansa e delicada" — algumas traduções dizem "um silêncio sutil". É nesse som quase inaudível que Elias cobre o rosto, reconhecendo a presença.', aplicacao = 'A resposta que você espera pode não vir do jeito espalhafatoso que você imaginou. Às vezes exige estar quieto o suficiente pra notar algo sutil.', conexao = 'Salmos 46:10 traz a mesma instrução: "aquietai-vos, e sabei que eu sou Deus".' where sort_order = 38;
update public.hero_messages set slug = 'naamã-lavou-se-num-rio-comum', reference = '2 Reis 5', contexto = 'Naamã era um general sírio poderoso, mas leproso, que viaja até Israel buscando cura através do profeta Eliseu, esperando um ritual à altura de seu status.', capitulo = 'Eliseu nem sai para recebê-lo — manda um mensageiro dizer para se lavar sete vezes no rio Jordão. Naamã fica indignado com a simplicidade e quase vai embora sem se curar, até seus servos o convencerem a tentar.', aplicacao = 'Orgulho às vezes rejeita justamente a solução mais simples, porque ela não parece proporcional ao tamanho do problema.', conexao = '1 Coríntios 1:25 fala da mesma lógica invertida: a loucura de Deus é mais sábia que a sabedoria humana.' where sort_order = 39;
update public.hero_messages set slug = 'ester-para-esta-hora', reference = 'Ester 4', contexto = 'Ester, rainha judia escondendo sua origem, descobre um plano de extermínio contra seu povo. Seu tio Mordecai a desafia a interceder junto ao rei, mesmo sob risco de morte por se apresentar sem ser chamada.', capitulo = 'Mordecai lhe diz que talvez ela tenha chegado à posição de rainha "para tal tempo como este". Ester pede jejum ao povo e decide agir, dizendo: "se eu perecer, pereço".', aplicacao = 'A posição em que você está agora, mesmo que pareça acidental, pode ser exatamente o lugar de onde algo importante depende de você agir.', conexao = 'Efésios 2:10 fala de sermos "criados [...] para boas obras, as quais Deus preparou de antemão" — posição com propósito, não coincidência.' where sort_order = 40;
update public.hero_messages set slug = 'neemias-muro-com-arma', reference = 'Neemias 4', contexto = 'Neemias lidera a reconstrução do muro de Jerusalém, destruído havia décadas, enfrentando zombaria e ameaças de ataque de grupos vizinhos hostis ao projeto.', capitulo = 'A solução foi trabalhar com uma ferramenta numa mão e uma arma na outra, com metade do povo vigiando enquanto a outra metade construía. Neemias organiza o povo por família, perto de suas próprias casas.', aplicacao = 'Construir algo que importa raramente acontece num ambiente tranquilo. Às vezes é preciso trabalhar e se defender ao mesmo tempo, sem esperar que a oposição pare primeiro.', conexao = 'Efésios 6:11-17 descreve a mesma dualidade espiritual: vestir a armadura de Deus para o trabalho e a resistência juntos.' where sort_order = 41;
update public.hero_messages set slug = 'jo-recusou-respostas-faceis', reference = 'Jó 1-2', contexto = 'Jó era descrito como íntegro e temente a Deus, quando perde bens, filhos e saúde numa sequência de tragédias, sem nenhuma explicação dada a ele no momento.', capitulo = 'Seus amigos passam o livro tentando explicar o sofrimento como punição por pecado escondido. Jó recusa essa resposta fácil, mas também recusa amaldiçoar a Deus — ele insiste em ser sincero sobre a dor sem desistir da fé.', aplicacao = 'Discordar em voz alta, questionar, sentir raiva de uma situação injusta — nada disso é o mesmo que abandonar a fé. É possível fazer as duas coisas ao mesmo tempo.', conexao = 'Salmos 13 é outro exemplo de lamento honesto que termina em confiança, sem pular a parte difícil no meio.' where sort_order = 42;
update public.hero_messages set slug = 'jo-recebeu-presenca-nao-explicacao', reference = 'Jó 38-42', contexto = 'Depois de 37 capítulos de debate sobre a causa do sofrimento de Jó, Deus finalmente responde — não com uma explicação, mas com uma série de perguntas sobre a criação do universo.', capitulo = 'Deus nunca explica por que Jó sofreu. Em vez disso, mostra a imensidão do que criou e sustenta. Jó responde: "eu te conhecia só de ouvir falar, mas agora meus olhos te veem" — e isso é suficiente para ele.', aplicacao = 'Às vezes a pergunta "por quê" nunca recebe resposta completa nesta vida. O que muda tudo não é entender, é a certeza de não estar sozinho no meio do que não se entende.', conexao = 'Romanos 11:33-34 termina num tom parecido: os caminhos de Deus "inescrutáveis", além de explicação total.' where sort_order = 43;
update public.hero_messages set slug = 'salmo-23-o-pastor', reference = 'Salmos 23', contexto = 'Tradicionalmente atribuído a Davi, que passou anos como pastor de ovelhas antes de ser rei — a imagem do pastor não era abstrata para ele, era memória concreta de trabalho.', capitulo = 'O salmo descreve cuidado prático: pastagens, águas tranquilas, uma vara e um cajado para proteção, uma mesa preparada mesmo "na presença dos meus inimigos". Termina com a certeza de bondade e misericórdia seguindo o autor todos os dias.', aplicacao = 'Confiança dessa profundidade normalmente não nasce de uma vida fácil — nasce de alguém que já foi perseguido e ainda assim experimentou provisão no meio da perseguição.', conexao = 'João 10:11 retoma a imagem: "Eu sou o bom pastor; o bom pastor dá a sua vida pelas ovelhas".' where sort_order = 44;
update public.hero_messages set slug = 'vale-da-sombra-da-morte', reference = 'Salmos 23:4', contexto = 'No meio do salmo do pastor, o texto muda de tom por um verso, reconhecendo um vale sombrio antes de voltar à confiança tranquila.', capitulo = 'O versículo não promete desviar do vale: "ainda que eu andasse" pressupõe atravessar mesmo. A segurança declarada é companhia — "tu estás comigo" — não ausência de perigo.', aplicacao = 'Fé não promete rota alternativa que evite todo vale difícil. Promete companhia dentro dele, o que muda como você atravessa, não se você atravessa.', conexao = 'Isaías 43:2 confirma essa promessa de presença em vez de desvio: "quando passares pelas águas, eu serei contigo".' where sort_order = 45;
update public.hero_messages set slug = 'de-manha-ouve-minha-voz', reference = 'Salmos 5:3', contexto = 'Este salmo é atribuído a Davi já como rei, alguém com um reino inteiro para administrar e decisões constantes para tomar.', capitulo = 'Mesmo com essa responsabilidade, o hábito descrito é buscar a Deus logo pela manhã, antes de qualquer outra coisa, e esperar em silêncio pela resposta.', aplicacao = 'O que ocupa o primeiro espaço do seu dia geralmente revela sua prioridade real, mais do que qualquer coisa que você diga valorizar.', conexao = 'Marcos 1:35 mostra Jesus fazendo o mesmo: levantando de madrugada, antes de todos, para orar sozinho.' where sort_order = 46;
update public.hero_messages set slug = 'tudo-tem-seu-tempo', reference = 'Eclesiastes 3:1-8', contexto = 'Eclesiastes é tradicionalmente atribuído a Salomão, escrito depois de ter experimentado riqueza, poder, prazer e conhecimento em excesso — e concluído que nada disso, sozinho, satisfaz.', capitulo = 'O capítulo lista pares opostos — tempo de nascer e morrer, plantar e colher, chorar e rir — sugerindo que a vida se move em estações, não numa linha reta de progresso constante.', aplicacao = 'A fase difícil que você vive agora não é a vida inteira, é uma estação dentro dela. Reconhecer isso não apressa o tempo, mas muda como você o atravessa.', conexao = 'Gálatas 6:9 fala do "tempo próprio" da colheita — outra forma de dizer que existe um relógio que não é o seu.' where sort_order = 47;
update public.hero_messages set slug = 'confia-nao-no-teu-entendimento', reference = 'Provérbios 3:5-6', contexto = 'Provérbios é uma coleção de ditos de sabedoria atribuídos majoritariamente a Salomão, voltados a formar caráter prático, não teoria abstrata.', capitulo = 'O conselho não pede para desligar a razão, pede para não fazer dela a única bússola: "não te estribes no teu próprio entendimento [...] e ele endireitará as tuas veredas".', aplicacao = 'Existe diferença entre pensar com cuidado e confiar cegamente na própria análise. A segunda coisa, sozinha, tem limite — sempre existe informação que você não tem.', conexao = 'Isaías 55:8-9 reforça a mesma ideia, num tom mais direto: os pensamentos de Deus não são os seus pensamentos.' where sort_order = 48;
update public.hero_messages set slug = 'resposta-branda-desvia-o-furor', reference = 'Provérbios 15:1', contexto = 'Está no meio de uma sequência de provérbios sobre fala, língua e comunicação, comparando o efeito de palavras duras contra palavras suaves numa mesma situação de conflito.', capitulo = '"A resposta branda desvia o furor, mas a palavra dura suscita a ira" — o mesmo conteúdo dito de formas diferentes produz resultados completamente opostos.', aplicacao = 'Antes de discutir o que dizer numa conversa difícil, vale parar no como. O tom muitas vezes decide o rumo da conversa mais do que o conteúdo.', conexao = 'Tiago 1:19 recomenda o preparo antes da resposta: pronto para ouvir, tardio para falar, tardio para se irar.' where sort_order = 49;
update public.hero_messages set slug = 'isaias-ai-de-mim', reference = 'Isaías 6', contexto = 'Isaías tem uma visão de Deus no templo, cercado por serafins declarando Sua santidade, no ano da morte do rei Uzias — um momento de incerteza política em Judá.', capitulo = 'Diante da visão, a primeira reação de Isaías não é entusiasmo, é "ai de mim [...] sou homem de lábios impuros". Só depois de um serafim purificar seus lábios com uma brasa é que ele se oferece para a missão: "eis-me aqui, envia-me a mim".', aplicacao = 'Reconhecer a própria insuficiência antes de aceitar um chamado não é fraqueza — costuma ser o que garante que a missão não vire sobre o mensageiro.', conexao = '1 Timóteo 1:15 traz a mesma ordem: Paulo se descreve como "o principal" dos pecadores logo antes de descrever seu ministério.' where sort_order = 50;
update public.hero_messages set slug = 'aguias-renovam-forcas', reference = 'Isaías 40:28-31', contexto = 'Este capítulo é dirigido a um povo cansado, no fim do livro de Isaías que trata do exílio e da esperança de restauração — não a um povo em momento de vitória.', capitulo = 'O texto contrasta o cansaço até de jovens fortes com a promessa de que "os que esperam no Senhor renovarão as forças [...] subirão com asas como águias".', aplicacao = 'Essa promessa não foi escrita para gente cheia de energia — foi escrita justamente para quem está no fim das próprias forças.', conexao = '2 Coríntios 4:16 traz o mesmo tipo de renovação: "ainda que o nosso homem exterior se corrompa, o interior se renova de dia em dia".' where sort_order = 51;
update public.hero_messages set slug = 'jeremias-jovem-demais', reference = 'Jeremias 1:4-8', contexto = 'Jeremias é chamado ainda jovem para ser profeta, numa época de crise política e espiritual em Judá, pouco antes da destruição de Jerusalém pelos babilônios.', capitulo = 'Sua primeira reação ao chamado é objetar: "não sei falar, porque sou moço". Deus responde que já o conhecia antes de formá-lo no ventre, e que iria com ele aonde fosse enviado.', aplicacao = 'Idade, experiência ou preparo percebido como insuficiente não são argumento válido contra um chamado que já vem com a promessa de companhia.', conexao = '1 Timóteo 4:12 dá a mesma orientação a outro jovem líder, Timóteo: "ninguém despreze a tua mocidade".' where sort_order = 52;
update public.hero_messages set slug = 'antes-que-te-formasse', reference = 'Jeremias 1:5', contexto = 'Parte do mesmo chamado de Jeremias, essa frase específica estabelece que o conhecimento e o propósito de Deus para ele antecedem até seu nascimento.', capitulo = '"Antes que te formasse no ventre, eu te conheci, e antes que saísses da madre, te santifiquei" — a escolha não foi uma reação a algo que Jeremias fez, foi anterior a qualquer ação dele.', aplicacao = 'Isso muda a pergunta de "eu mereço estar aqui" para "eu já era esperado aqui, antes de qualquer mérito entrar em jogo".', conexao = 'Salmos 139:13-16 desenvolve a mesma ideia em detalhe, descrevendo Deus tecendo a pessoa ainda no ventre.' where sort_order = 53;
update public.hero_messages set slug = 'oleiro-remodela-o-vaso', reference = 'Jeremias 18:1-6', contexto = 'Deus manda Jeremias descer à casa de um oleiro para observar seu trabalho, como ilustração viva para uma mensagem ao povo de Judá.', capitulo = 'Quando o vaso que o oleiro estava fazendo se estraga em suas mãos, ele não descarta o barro — refaz outro vaso com o mesmo material. Deus compara Israel a esse barro nas mãos do oleiro.', aplicacao = 'Um plano que "deu errado" na primeira tentativa não significa material descartado. Pode significar simplesmente remodelagem em andamento.', conexao = 'Romanos 9:20-21 usa a mesma imagem do oleiro para falar sobre confiar no propósito de quem molda, mesmo sem entender o processo inteiro.' where sort_order = 54;
update public.hero_messages set slug = 'vale-de-ossos-secos', reference = 'Ezequiel 37:1-14', contexto = 'Ezequiel profetiza durante o exílio babilônico, para um povo que se sentia espiritualmente morto, sem esperança de restauração nacional ou espiritual.', capitulo = 'Deus o leva a um vale cheio de ossos completamente secos e pergunta se podem viver. Ao profetizar sobre eles, os ossos se juntam, ganham tendões, carne e finalmente respiração — voltando à vida um a um.', aplicacao = 'Alguma coisa na sua vida pode parecer seca e morta demais para qualquer restauração. A imagem bíblica de reconstrução não começa pelo que já está vivo — começa exatamente pelo que parecia definitivamente acabado.', conexao = 'João 11 mostra a mesma lógica com Lázaro, morto havia quatro dias antes de Jesus chamá-lo de volta.' where sort_order = 55;
update public.hero_messages set slug = 'daniel-nao-se-contaminou', reference = 'Daniel 1', contexto = 'Daniel e seus amigos foram levados cativos para a Babilônia ainda jovens, sem nenhum poder sobre a própria situação, e recebem ordem de comer da mesa real — alimento que violava suas convicções.', capitulo = 'Daniel propõe um teste: comer apenas vegetais por dez dias, e comparar o resultado com os que comeram da mesa real. Ao final, ele e os amigos aparecem mais saudáveis, e são favorecidos pelo próprio rei.', aplicacao = 'Convicção não depende de ter controle da situação inteira. Mesmo sem poder sobre onde você está, ainda existe espaço de escolha sobre como se posicionar dentro dela.', conexao = 'Romanos 12:2 pede o mesmo princípio de forma mais ampla: não se conformar, mas se transformar por dentro, mesmo em ambiente contrário.' where sort_order = 56;
update public.hero_messages set slug = 'fornalha-mesmo-se-nao-livrar', reference = 'Daniel 3', contexto = 'Sadraque, Mesaque e Abednego, amigos de Daniel, se recusam a adorar uma estátua de ouro erguida pelo rei Nabucodonosor, sob pena de morte numa fornalha ardente.', capitulo = 'Diante do ultimato do rei, eles respondem que Deus pode livrá-los — mas acrescentam: "e se não livrar, sabe, ó rei, que não serviremos os teus deuses". Eles são jogados na fornalha e saem sem nenhum cheiro de fogo.', aplicacao = 'Fé genuína não é aposta em resultado garantido. É lealdade decidida mesmo antes de saber como a história vai terminar.', conexao = 'Hebreus 11:35 lembra que nem todo ato de fé termina em livramento visível — alguns terminam em sofrimento, e ainda assim são contados como fé.' where sort_order = 57;
update public.hero_messages set slug = 'daniel-cova-dos-leoes', reference = 'Daniel 6', contexto = 'Daniel, já idoso e ocupando alto cargo na corte, é alvo de uma armadilha política: uma lei que proíbe orar a qualquer deus além do rei, criada especificamente para incriminá-lo.', capitulo = 'Daniel continua orando três vezes ao dia como sempre fez, sabendo da lei, e é jogado na cova dos leões. Na manhã seguinte, o rei corre até lá e Daniel responde que Deus enviou um anjo que fechou a boca dos leões.', aplicacao = 'Manter uma prática que sustenta sua fé, mesmo sob pressão para abandoná-la, é o tipo de constância que sustenta a pessoa quando a crise chega.', conexao = '1 Pedro 5:8-9 usa a mesma imagem de leão, agora como adversário espiritual a ser resistido firme na fé.' where sort_order = 58;
update public.hero_messages set slug = 'jonas-fugiu-na-direcao-contraria', reference = 'Jonas 1', contexto = 'Jonas recebe a ordem de pregar arrependimento a Nínive, capital do império assírio, inimigo histórico de Israel. Em vez de obedecer, ele compra passagem num navio na direção completamente oposta.', capitulo = 'Uma tempestade forte ameaça afundar o navio, e os marinheiros descobrem que Jonas é a causa depois de lançarem sortes. Jonas é lançado ao mar e engolido por um grande peixe, onde passa três dias antes de ser cuspido na praia.', aplicacao = 'Fugir de um chamado não cancela o chamado — só adiciona uma tempestade no caminho até você aceitar de qualquer jeito o que já era pedido.', conexao = 'Mateus 12:40 usa os três dias de Jonas no peixe como figura da ressurreição de Jesus, três dias depois no sepulcro.' where sort_order = 59;
update public.hero_messages set slug = 'jonas-bravo-com-o-perdao', reference = 'Jonas 4', contexto = 'Depois de finalmente pregar em Nínive, a cidade inteira se arrepende e Deus decide não destruí-la — exatamente o resultado que, em teoria, Jonas deveria querer.', capitulo = 'Em vez de comemorar, Jonas fica furioso e admite que fugiu antes justamente porque sabia que Deus era misericordioso e perdoaria. Ele preferia ver a cidade inimiga destruída a vê-la perdoada.', aplicacao = 'Às vezes o maior obstáculo para alguém experimentar graça não é a distância dessa pessoa de Deus — é a nossa resistência em ver a graça alcançar quem julgamos não merecer.', conexao = 'Lucas 15:28-30 tem o mesmo conflito na parábola do filho pródigo: o irmão mais velho, ressentido com a festa pelo perdão do mais novo.' where sort_order = 60;
update public.hero_messages set slug = 'ninguem-despreze-tua-mocidade', reference = '1 Timóteo 4:12', contexto = 'Paulo escreve a Timóteo, um jovem líder que ele mesmo formou, colocado à frente de uma igreja estabelecida onde membros mais velhos poderiam questionar sua autoridade pela idade.', capitulo = 'Em vez de pedir que Timóteo espere ficar mais velho, Paulo instrui que ele seja exemplo em palavra, conduta, amor, fé e pureza — a autoridade viria do caráter demonstrado, não da idade alcançada.', aplicacao = 'Idade não é a mesma coisa que autoridade, e falta de anos não é motivo suficiente pra adiar responsabilidade que já está diante de você.', conexao = '1 Samuel 16:7 traz o mesmo princípio: Deus olha o coração, não a aparência externa que inclui idade.' where sort_order = 61;
update public.hero_messages set slug = 'jesus-nasceu-em-lugar-comum', reference = 'Lucas 2:1-7', contexto = 'Um decreto de recenseamento romano obriga José e Maria a viajarem até Belém, onde não encontram lugar na hospedaria e Jesus nasce provavelmente num estábulo, com uma manjedoura como berço.', capitulo = 'Nenhum detalhe do nascimento sugere grandiosidade visível — uma viagem forçada, falta de acomodação, um casal comum numa cidade pequena. A grandeza do acontecimento não corresponde às condições em que acontece.', aplicacao = 'Aquilo que vai se tornar imenso não precisa começar parecendo imenso. As condições do início raramente predizem o alcance do que está começando.', conexao = 'Miqueias 5:2 já tinha profetizado séculos antes que de Belém, "pequena entre milhares", sairia o governante prometido.' where sort_order = 62;
update public.hero_messages set slug = 'pastores-foram-os-primeiros', reference = 'Lucas 2:8-20', contexto = 'Pastores eram considerados socialmente marginais na época, com trabalho que os deixava ritualmente impuros e impedidos de participar plenamente da vida religiosa formal.', capitulo = 'É a esse grupo, e não a sacerdotes ou autoridades, que os anjos anunciam o nascimento do Salvador. Os pastores deixam os rebanhos e vão correndo verificar o que foi dito.', aplicacao = 'A notícia mais importante da história foi dada primeiro a quem estava disponível pra ouvir, não a quem tinha status pra merecer ouvir primeiro.', conexao = '1 Coríntios 1:26-29 confirma o padrão: Deus escolhe frequentemente o que o mundo considera insignificante.' where sort_order = 63;
update public.hero_messages set slug = 'simeao-esperou-a-vida-toda', reference = 'Lucas 2:25-35', contexto = 'Simeão era um homem idoso em Jerusalém, descrito como justo e piedoso, a quem tinha sido revelado que não morreria antes de ver o Messias.', capitulo = 'Guiado pelo Espírito, ele vai ao templo exatamente no momento em que José e Maria trazem o bebê Jesus, e o reconhece na hora, sem nenhum anúncio externo, tomando-o nos braços e declarando sua missão cumprida.', aplicacao = 'Esperar com atenção ativa — não apenas esperar passivamente — é o que permite reconhecer o momento certo quando ele finalmente chega, mesmo sem aviso.', conexao = 'Lucas 2:36-38 traz Ana, profetisa idosa, tendo o mesmo tipo de reconhecimento no mesmo momento.' where sort_order = 64;
update public.hero_messages set slug = 'quarenta-dias-antes-de-comecar', reference = 'Mateus 4:1-11', contexto = 'Logo depois de ser batizado — o momento em que uma voz do céu o declara Filho amado — Jesus é levado pelo Espírito ao deserto para ser tentado, antes de iniciar qualquer ministério público.', capitulo = 'Quarenta dias de jejum antecedem as três tentativas do diabo de desviá-lo: transformar pedra em pão, jogar-se do templo, e adorar o diabo em troca de todos os reinos do mundo. Jesus responde às três com Escritura.', aplicacao = 'Preparo sério muitas vezes acontece longe de qualquer plateia, num período difícil que ninguém testemunha, antes de qualquer coisa pública começar.', conexao = 'Hebreus 4:15 lembra que Jesus "foi tentado em tudo, à nossa semelhança", o que torna Sua compreensão da fraqueza humana real, não teórica.' where sort_order = 65;
update public.hero_messages set slug = 'pedra-em-pao', reference = 'Mateus 4:3-4', contexto = 'A primeira das três tentações no deserto vem depois de 40 dias de jejum, quando a fome de Jesus certamente estava no limite — o momento mais óbvio para usar poder a favor do próprio conforto.', capitulo = 'O diabo propõe transformar pedras em pão. Jesus responde citando Deuteronômio: "nem só de pão viverá o homem, mas de toda palavra que sai da boca de Deus" — recusando usar poder disponível para resolver desconforto imediato.', aplicacao = 'Ter a capacidade de resolver algo agora não significa que esse seja o momento certo de usar essa capacidade. Nem todo poder disponível deveria ser usado imediatamente.', conexao = 'Filipenses 4:12 fala da mesma disciplina: saber passar necessidade sem que isso abale o essencial.' where sort_order = 66;
update public.hero_messages set slug = 'jesus-chamou-no-meio-do-trabalho', reference = 'Mateus 4:18-22', contexto = 'Simão Pedro, André, Tiago e João eram pescadores profissionais, trabalhando com suas redes no mar da Galileia quando Jesus passa e os chama.', capitulo = 'Não há preparação prévia registrada, nenhum evento espiritual especial antes do chamado — Jesus simplesmente diz "segui-me", e o texto relata que eles deixam as redes imediatamente.', aplicacao = 'Chamado importante geralmente interrompe a rotina exatamente onde ela está acontecendo, em vez de esperar um momento mais conveniente ou mais espiritual para acontecer.', conexao = '1 Coríntios 1:26-27 lembra que os primeiros chamados raramente eram os mais qualificados academicamente — eram os disponíveis.' where sort_order = 67;
update public.hero_messages set slug = 'bem-aventurados-os-que-choram', reference = 'Mateus 5:4', contexto = 'Está no Sermão do Monte, a coleção mais extensa de ensino de Jesus, dirigida a uma multidão que incluía gente pobre, doente e socialmente marginalizada.', capitulo = 'As bem-aventuranças invertem a lógica comum de bênção: pobres de espírito, os que choram, os mansos, os perseguidos — todos chamados bem-aventurados, não apesar da dificuldade, mas dentro dela.', aplicacao = 'A dor que você sente agora não te coloca fora da bênção. O texto coloca a dor dentro dela, prometendo consolo, não a ausência da dor primeiro.', conexao = '2 Coríntios 1:3-4 chama Deus de "Pai das misericórdias e Deus de toda a consolação" — o mesmo tema, décadas depois.' where sort_order = 68;
update public.hero_messages set slug = 'nao-andeis-ansiosos-pelo-amanha', reference = 'Mateus 6:25-34', contexto = 'Ainda no Sermão do Monte, Jesus fala a uma audiência majoritariamente pobre, sem garantias econômicas, sobre comida, roupa e o dia seguinte.', capitulo = 'Ele aponta para as aves do céu, que não semeiam nem colhem, e os lírios do campo, mais vestidos que Salomão em toda sua glória, como evidência de cuidado que não depende do próprio esforço ansioso.', aplicacao = 'A instrução não vem de alguém que nunca passou necessidade — vem de alguém vivendo entre gente que também não sabia o que ia comer amanhã.', conexao = 'Filipenses 4:6 traduz a mesma ideia em ação prática: em vez de ansiedade, apresentar pedidos com ação de graças.' where sort_order = 69;
update public.hero_messages set slug = 'amigos-desceram-pelo-teto', reference = 'Marcos 2:1-12', contexto = 'Jesus estava ensinando numa casa lotada em Cafarnaum quando quatro amigos trazem um paralítico numa maca, mas não conseguem chegar até a porta por causa da multidão.', capitulo = 'Em vez de desistir, eles sobem no telhado, abrem um buraco e baixam a maca bem na frente de Jesus. O texto diz que Jesus viu "a fé deles" — no plural, dos amigos — antes de curar o paralítico.', aplicacao = 'Às vezes você não consegue chegar sozinho até onde precisa. A fé de quem está ao seu lado, disposta a abrir caminho por você, também conta.', conexao = 'Eclesiastes 4:9-10 fala da mesma força coletiva: "se um cair, o outro o levanta".' where sort_order = 70;
update public.hero_messages set slug = 'mulher-no-poco-no-horario-certo', reference = 'João 4:1-26', contexto = 'Mulheres samaritanas normalmente iam buscar água de manhã cedo, no fresco do dia, em grupo. Essa mulher vai sozinha ao meio-dia — provavelmente evitando o julgamento social por sua vida pessoal.', capitulo = 'Jesus, um judeu, quebra duas barreiras sociais ao falar com ela — de gênero e de etnia — e conduz a conversa até revelar que sabe de toda a sua história pessoal, sem condená-la por isso.', aplicacao = 'O horário que você escolhe pra evitar as pessoas pode ser exatamente o horário em que alguém escolhe estar lá, esperando por você.', conexao = 'João 8:1-11 tem o mesmo padrão com a mulher pega em adultério: encontro sem condenação antes de qualquer mudança.' where sort_order = 71;
update public.hero_messages set slug = 'cinco-paes-e-dois-peixes', reference = 'João 6:1-13', contexto = 'Uma multidão de milhares seguiu Jesus até um lugar deserto, sem provisão suficiente de comida, no fim de um longo dia de ensino.', capitulo = 'Um menino oferece cinco pães e dois peixes — quantidade risível diante da multidão. Jesus abençoa o pouco, distribui, e sobra comida depois de todos comerem, com doze cestos cheios de resto.', aplicacao = 'O que você tem para oferecer pode parecer pequeno demais para o tamanho do problema. A multiplicação não depende da quantidade inicial, depende de estar disposto a oferecer o pouco que existe.', conexao = '2 Coríntios 9:6 fala do mesmo princípio de generosidade: quem semeia pouco colhe pouco, mas o que importa é semear.' where sort_order = 72;
update public.hero_messages set slug = 'tempestade-acalmada', reference = 'Marcos 4:35-41', contexto = 'Jesus e os discípulos atravessam o mar da Galileia à noite, depois de um dia inteiro de ensino, quando uma tempestade forte ameaça afundar o barco.', capitulo = 'Jesus dorme na popa durante a tempestade. Os discípulos, em pânico, o acordam gritando que vão morrer. Ele acalma o vento e o mar com uma palavra, e depois pergunta por que eles ainda não tinham fé.', aplicacao = 'A pergunta em momentos de crise raramente é sobre a gravidade da tempestade — é sobre onde está sua confiança enquanto ela ainda está passando.', conexao = 'Isaías 43:2 promete a mesma companhia em meio às águas: "não te afogarão".' where sort_order = 73;
update public.hero_messages set slug = 'pedro-afundou-olhando-o-vento', reference = 'Mateus 14:22-33', contexto = 'Depois de alimentar a multidão, Jesus manda os discípulos seguirem de barco enquanto ele ora sozinho num monte. De madrugada, ele caminha sobre o mar em direção a eles, em meio a outra tempestade.', capitulo = 'Pedro pede para ir ao encontro dele andando sobre a água também, e consegue — enquanto olha para Jesus. No momento em que percebe o vento forte e desvia a atenção, começa a afundar, e Jesus o segura imediatamente.', aplicacao = 'A queda muitas vezes começa exatamente no instante em que a atenção sai de onde deveria estar e vai para o tamanho do problema ao redor.', conexao = 'Hebreus 12:2 recomenda o mesmo foco: "fitando os olhos em Jesus", especialmente no meio da corrida difícil.' where sort_order = 74;
update public.hero_messages set slug = 'quem-nao-tem-pecado', reference = 'João 8:1-11', contexto = 'Escribas e fariseus trazem a Jesus uma mulher apanhada em adultério, citando a lei de Moisés que mandava apedrejá-la — uma armadilha para testar se ele contradiria a lei ou a misericórdia.', capitulo = 'Jesus se abaixa e escreve no chão, depois diz: "aquele que dentre vós está sem pecado seja o primeiro que atire pedra contra ela". Um a um, os acusadores se retiram, começando pelos mais velhos, até sobrar só ela e Jesus.', aplicacao = 'Antes de condenar publicamente o erro de alguém, vale medir a própria régua pelo mesmo padrão que está sendo aplicado ao outro.', conexao = 'Romanos 2:1 traz a mesma advertência: quem julga o outro pratica coisas parecidas e não escapa do próprio julgamento.' where sort_order = 75;
update public.hero_messages set slug = 'zaqueu-subiu-so-para-ver', reference = 'Lucas 19:1-10', contexto = 'Zaqueu era chefe dos publicanos em Jericó, coletor de impostos rico e desprezado pela população por colaborar com Roma. Baixo de estatura, não conseguia ver Jesus por cima da multidão.', capitulo = 'Ele sobe numa figueira brava só para conseguir ver de longe, sem esperar ser notado de volta. Jesus para exatamente embaixo daquela árvore, olha para cima e convida-se para a casa dele.', aplicacao = 'O esforço de buscar, mesmo escondido e sem expectativa de retorno, muitas vezes é visto exatamente por quem você estava tentando enxergar.', conexao = 'Tiago 4:8 promete a mesma dinâmica: "aproximai-vos de Deus, e ele se aproximará de vós".' where sort_order = 76;
update public.hero_messages set slug = 'filho-prodigo-nao-terminou-o-discurso', reference = 'Lucas 15:11-24', contexto = 'Um filho mais novo pede sua herança antecipada, gasta tudo numa vida dissoluta longe de casa, e volta arruinado, ensaiando um discurso de arrependimento para pedir apenas para ser tratado como empregado.', capitulo = 'O pai o vê ainda de longe, corre ao seu encontro e o abraça antes de qualquer palavra completa. Ele interrompe o discurso ensaiado do filho para mandar preparar uma festa de restauração completa.', aplicacao = 'Às vezes a resposta a um arrependimento sincero chega antes mesmo de você terminar de explicar o quanto errou — a restauração não espera o discurso perfeito.', conexao = 'Romanos 5:8 traz a mesma antecipação: "Deus prova o seu amor para conosco em que Cristo morreu por nós, sendo nós ainda pecadores".' where sort_order = 77;
update public.hero_messages set slug = 'irmao-mais-velho-de-fora-da-festa', reference = 'Lucas 15:25-32', contexto = 'Na mesma parábola do filho pródigo, o irmão mais velho, que ficou trabalhando fielmente em casa o tempo todo, volta do campo e encontra uma festa em celebração ao irmão que voltou.', capitulo = 'Ele se recusa a entrar, ressentido por nunca ter recebido nem um cabrito para festejar com os amigos, apesar de anos de serviço fiel. O pai sai e o convida, dizendo que tudo o que é dele também pertence ao filho mais velho.', aplicacao = 'Fazer tudo certo por anos pode gerar um tipo diferente de amargura quando alguém que "errou tudo" recebe a mesma festa — e essa amargura também precisa ser tratada, não só ignorada.', conexao = 'Mateus 20:1-16 traz o mesmo desconforto na parábola dos trabalhadores da vinha, todos pagos igualmente independente da hora que começaram.' where sort_order = 78;
update public.hero_messages set slug = 'ovelha-perdida-vale-a-busca', reference = 'Lucas 15:3-7', contexto = 'Jesus conta essa parábola em resposta a fariseus e escribas que reclamavam dele receber e comer com "pecadores" — pessoas socialmente rejeitadas.', capitulo = 'Um pastor com cem ovelhas, ao perceber que uma se perdeu, deixa as noventa e nove no campo para procurar a única que faltava, e celebra ao encontrá-la mais do que pelas que nunca se perderam.', aplicacao = 'O valor de uma pessoa, na lógica dessa história, não se mede pela quantidade das outras que já estão seguras — cada uma que se perde importa o suficiente para uma busca inteira.', conexao = 'Ezequiel 34:11-16 já tinha essa imagem do pastor que busca as ovelhas perdidas, séculos antes.' where sort_order = 79;
update public.hero_messages set slug = 'semente-em-terra-boa', reference = 'Mateus 13:1-23', contexto = 'Jesus ensina essa parábola a uma multidão à beira do mar da Galileia, usando uma imagem agrícola familiar a quase todos os ouvintes daquele tempo e lugar.', capitulo = 'A mesma semente cai em quatro tipos de solo — caminho, pedregal, espinhos e terra boa — e só num deles produz fruto. A diferença não está na semente, está na condição do terreno que a recebe.', aplicacao = 'Receber bem uma mensagem importante — estar disposto, atento, sem distrações competindo — importa tanto quanto a qualidade da própria mensagem.', conexao = 'Tiago 1:21 pede a mesma disposição: receber "com mansidão a palavra em vós enxertada".' where sort_order = 80;
update public.hero_messages set slug = 'grao-de-mostarda', reference = 'Mateus 13:31-32', contexto = 'Jesus descreve o Reino dos Céus usando uma das menores sementes conhecidas na região, comparando-a ao que ela se torna depois de plantada.', capitulo = 'O grão de mostarda é "a menor de todas as sementes", mas cresce até se tornar a maior das hortaliças, grande o suficiente para pássaros fazerem ninho em seus ramos.', aplicacao = 'O tamanho de um começo não é indicador confiável do tamanho do que ele pode se tornar. Coisas pequenas plantadas com constância crescem além do que parecia possível no início.', conexao = 'Zacarias 4:10 pergunta diretamente: "quem despreza o dia dos pequenos começos?".' where sort_order = 81;
update public.hero_messages set slug = 'talento-enterrado-por-medo', reference = 'Mateus 25:14-30', contexto = 'Jesus conta essa parábola pouco antes de sua crucificação, num bloco de ensino sobre estar preparado para o retorno do Reino, usando a imagem de um senhor que distribui talentos a três servos.', capitulo = 'Dois servos investem o que receberam e dobram o valor. O terceiro, com medo de perder o que tinha, enterra seu talento no chão — e é justamente esse medo que o senhor repreende ao voltar, não o tamanho do resultado.', aplicacao = 'Evitar o risco de arriscar também é uma forma de risco, só que mais silenciosa — o custo de não tentar frequentemente aparece só mais tarde.', conexao = '2 Timóteo 1:7 confirma o oposto do medo: "Deus não nos deu o espírito de temor, mas de fortaleza, e de amor, e de moderação".' where sort_order = 82;
update public.hero_messages set slug = 'marta-maria-melhor-parte', reference = 'Lucas 10:38-42', contexto = 'Jesus visita a casa de Marta e Maria em Betânia. Marta se ocupa preparando tudo para receber o convidado, enquanto Maria simplesmente se senta aos pés de Jesus para ouvir.', capitulo = 'Marta reclama que a irmã não ajuda, e pede a Jesus para mandá-la ajudar. Jesus responde que Marta está ansiosa com muitas coisas, mas Maria escolheu "a boa parte, que não lhe será tirada".', aplicacao = 'Nem toda tarefa urgente é a coisa certa a fazer no momento certo. Às vezes a prioridade real está em parar, não em produzir mais.', conexao = 'Salmos 46:10 pede o mesmo movimento: "aquietai-vos, e sabei que eu sou Deus", antes de qualquer ação.' where sort_order = 83;
update public.hero_messages set slug = 'lazaro-atraso-proposital', reference = 'João 11:1-44', contexto = 'Lázaro, amigo próximo de Jesus, adoece gravemente. As irmãs Marta e Maria mandam avisar Jesus, mas ele deliberadamente espera dois dias antes de ir, e Lázaro morre nesse intervalo.', capitulo = 'Quando Jesus finalmente chega, Lázaro já está morto há quatro dias. Diante do túmulo, Jesus chora — mesmo sabendo o que estava prestes a fazer — e então chama Lázaro para fora, vivo.', aplicacao = 'Um atraso que parece descaso pode, na verdade, estar reservando espaço para algo maior do que a solução rápida que você esperava.', conexao = '2 Pedro 3:9 fala da mesma tensão sobre tempo: o que parece demora pode ser paciência com um propósito maior em jogo.' where sort_order = 84;
update public.hero_messages set slug = 'jesus-chorou-mesmo-sabendo', reference = 'João 11:33-36', contexto = 'No mesmo episódio da morte de Lázaro, Jesus já sabia que ia ressuscitá-lo em minutos — e ainda assim, diante do túmulo e do choro das irmãs, ele próprio chora.', capitulo = 'É o versículo mais curto da Bíblia em português: "Chorou Jesus". A esperança da ressurreição iminente não impede a dor genuína diante da perda presente.', aplicacao = 'Ter esperança sobre o que vem depois não exige fingir que a dor de agora não existe. As duas coisas cabem juntas, ao mesmo tempo.', conexao = '1 Tessalonicenses 4:13 pede algo parecido: não deixar de sentir a perda, mas não a viver "como os que não têm esperança".' where sort_order = 85;
update public.hero_messages set slug = 'lavou-os-pes-de-quem-o-trairia', reference = 'João 13:1-17', contexto = 'Na última ceia, sabendo que seria traído e crucificado em poucas horas, Jesus se levanta, tira o manto e começa a lavar os pés dos discípulos — tarefa normalmente reservada a servos.', capitulo = 'Judas, que já tinha combinado a traição, também tem os pés lavados por Jesus, sem distinção. Jesus explica depois: "dei-vos exemplo, para que, como eu vos fiz, façais vós também".', aplicacao = 'Serviço genuíno, no exemplo dado, não escolhe quem merece receber. Ele se estende inclusive a quem está prestes a fazer o pior.', conexao = 'Romanos 5:8 traz a mesma lógica: Cristo morreu por nós "sendo nós ainda pecadores", não depois de merecermos.' where sort_order = 86;
update public.hero_messages set slug = 'nao-seja-como-eu-quero', reference = 'Mateus 26:36-46', contexto = 'No jardim do Getsêmani, horas antes de ser preso, Jesus ora sozinho enquanto os discípulos dormem por perto, sabendo exatamente o sofrimento que estava por vir.', capitulo = 'Ele pede três vezes que, se possível, aquele cálice passasse dele — um pedido humano e sincero — mas termina cada oração com "não seja como eu quero, mas como tu queres".', aplicacao = 'Obediência genuína não exige fingir que algo é fácil ou desejável. É possível pedir sinceramente por outro caminho e, ao mesmo tempo, escolher seguir o que for necessário.', conexao = 'Hebreus 5:7-8 descreve esse mesmo momento: Jesus aprendeu obediência através daquilo que sofreu, mesmo sendo Filho.' where sort_order = 87;
update public.hero_messages set slug = 'pedro-negou-tres-vezes', reference = 'Mateus 26:31-35, 69-75', contexto = 'Na última ceia, Pedro jura que nunca abandonaria Jesus, mesmo que todos os outros o fizessem. Jesus responde prevendo que, antes do galo cantar, Pedro o negaria três vezes.', capitulo = 'Horas depois, no pátio onde Jesus estava sendo julgado, Pedro nega conhecê-lo três vezes seguidas, com convicção crescente, até o galo cantar e ele se lembrar da previsão — saindo dali chorando amargamente.', aplicacao = 'A queda mais dura muitas vezes acontece logo depois da certeza mais convicta de que nunca cairíamos daquele jeito específico.', conexao = '1 Coríntios 10:12 alerta sobre isso: "aquele que cuida estar em pé, olhe não caia".' where sort_order = 88;
update public.hero_messages set slug = 'voce-me-ama-tres-vezes', reference = 'João 21:15-19', contexto = 'Depois da ressurreição, Jesus aparece aos discípulos à beira do mar da Galileia e prepara um café da manhã para eles, num encontro que inclui uma conversa direta com Pedro.', capitulo = 'Jesus pergunta a Pedro três vezes se ele o ama — o mesmo número de vezes que Pedro o negou. A cada resposta afirmativa, Jesus lhe dá uma missão: "apascenta as minhas ovelhas".', aplicacao = 'Restauração completa não apaga a memória do que aconteceu — ela devolve a mesma quantidade de confiança e propósito que existia antes da queda, apesar da memória continuar lá.', conexao = 'Lucas 22:31-32 mostra Jesus já orando por essa restauração antes mesmo da negação acontecer: "eu roguei por ti, para que a tua fé não desfaleça".' where sort_order = 89;
update public.hero_messages set slug = 'emaus-reconhecido-no-pao', reference = 'Lucas 24:13-35', contexto = 'Dois discípulos caminham de Jerusalém a Emaús, no dia da ressurreição, conversando desanimados sobre a morte de Jesus, sem saber que ele já tinha ressuscitado.', capitulo = 'Jesus caminha ao lado deles por horas, explicando as Escrituras, sem ser reconhecido — até se sentarem para comer, quando ele parte o pão, e nesse gesto específico os olhos deles se abrem.', aplicacao = 'A resposta que você procura pode estar caminhando ao seu lado há um bom tempo, sem que você a reconheça, até um gesto específico e familiar revelar o que sempre esteve ali.', conexao = 'João 20:14-16 traz o mesmo padrão com Maria Madalena, que só reconhece Jesus ressuscitado quando ele diz seu nome.' where sort_order = 90;
update public.hero_messages set slug = 'tome-a-duvida-sincera', reference = 'João 20:24-29', contexto = 'Tomé não estava presente na primeira aparição de Jesus ressuscitado aos discípulos, e se recusa a acreditar sem ver e tocar as marcas dos pregos com as próprias mãos.', capitulo = 'Uma semana depois, Jesus aparece novamente, especificamente com Tomé presente, e o convida a tocar as marcas. Tomé responde: "Senhor meu, e Deus meu", e Jesus fala da bênção reservada a quem crê sem ver.', aplicacao = 'Dúvida sincera, expressa em voz alta em vez de escondida, não fecha a porta de um encontro real — muitas vezes é justamente o convite para um encontro mais direto.', conexao = 'Judas 22 orienta o mesmo cuidado com quem duvida: "tende misericórdia de alguns que estão duvidando".' where sort_order = 91;
update public.hero_messages set slug = 'pentecostes-linguas-reunidas', reference = 'Atos 2:1-13', contexto = 'Cinquenta dias depois da Páscoa judaica, os discípulos estavam reunidos em Jerusalém quando o Espírito Santo desce sobre eles com um som de vento forte e línguas como fogo.', capitulo = 'Eles começam a falar em outras línguas, e uma multidão de judeus vindos de várias nações, cada um ouvindo em seu próprio idioma, fica perplexa — a mesma cidade que uma vez dividiu línguas em Babel agora as reúne.', aplicacao = 'O que uma vez separou pessoas por incompreensão pode ser revertido — comunicação e entendimento verdadeiro entre grupos diferentes ainda são possíveis.', conexao = 'Gênesis 11:1-9, a torre de Babel, é o espelho invertido dessa cena — de uma língua confundida em muitas, para muitas línguas se entendendo numa mesma mensagem.' where sort_order = 92;
update public.hero_messages set slug = 'saulo-interrompido-no-caminho', reference = 'Atos 9:1-19', contexto = 'Saulo (mais tarde Paulo) perseguia ativamente os primeiros cristãos, indo a caminho de Damasco com autorização para prendê-los, quando uma luz forte o derruba no chão.', capitulo = 'Uma voz pergunta por que ele o persegue, e Saulo fica cego por três dias até Ananias, um cristão relutante, ir orar por ele por instrução direta de Deus, e sua visão voltar.', aplicacao = 'Convicção forte na direção errada ainda pode ser interrompida e redirecionada — a intensidade de alguém contra algo não determina permanentemente de que lado essa pessoa vai ficar.', conexao = '1 Timóteo 1:13-16 é o próprio Paulo, anos depois, descrevendo essa mudança como exemplo da paciência de Deus.' where sort_order = 93;
update public.hero_messages set slug = 'paulo-e-silas-cantaram-na-cadeia', reference = 'Atos 16:16-34', contexto = 'Paulo e Silas são presos em Filipos depois de libertar uma escrava de um espírito de adivinhação, espancados publicamente e colocados no cepo, na parte mais interna da prisão.', capitulo = 'À meia-noite, ainda machucados, eles oram e cantam louvores, com os outros presos ouvindo. Um terremoto abre todas as portas, mas eles não fogem — e o carcereiro, prestes a se matar por achar que os presos escaparam, acaba se convertendo naquela mesma noite.', aplicacao = 'Louvor não precisa esperar a situação melhorar para começar. Às vezes ele acontece bem no meio da pior parte, antes de qualquer resposta visível chegar.', conexao = 'Tiago 1:2-3 pede a mesma postura: considerar motivo de alegria as provas, porque elas produzem paciência.' where sort_order = 94;
update public.hero_messages set slug = 'naufragio-comer-antes-de-continuar', reference = 'Atos 27:13-38', contexto = 'Paulo viaja como prisioneiro rumo a Roma quando o navio enfrenta uma tempestade violenta que dura duas semanas, deixando a tripulação exausta e sem comer, à beira do desespero.', capitulo = 'Depois de um anjo lhe garantir que todos sobreviveriam, Paulo insiste para que todos comam antes do naufrágio final, dizendo que isso era necessário para a sobrevivência de todos — fé não descartava cuidado físico básico.', aplicacao = 'Confiar numa promessa espiritual não substitui cuidar do corpo. As duas coisas andam juntas, não uma no lugar da outra.', conexao = '1 Coríntios 6:19-20 reforça a mesma integração: o corpo como parte da vida espiritual, não separado dela.' where sort_order = 95;
update public.hero_messages set slug = 'amor-para-uma-igreja-em-briga', reference = '1 Coríntios 13', contexto = 'Paulo escreve à igreja de Corinto, uma comunidade marcada por divisões internas, disputas sobre dons espirituais e comparações de status entre membros.', capitulo = 'Antes de descrever o amor como paciente e benigno, Paulo argumenta que sem amor, até os dons mais impressionantes — línguas, profecia, fé que move montanhas — não valem nada. O capítulo é correção, não poesia romântica isolada.', aplicacao = 'Esse texto tão citado em casamentos foi escrito originalmente para resolver brigas de comunidade — o que sugere que ele funciona tanto pra relação amorosa quanto pra qualquer grupo de pessoas tentando conviver.', conexao = 'Colossenses 3:14 resume a mesma ideia: "acima de tudo isto, o amor, que é o vínculo da perfeição".' where sort_order = 96;
update public.hero_messages set slug = 'fruto-que-cresce-devagar', reference = 'Gálatas 5:22-23', contexto = 'Paulo escreve aos Gálatas contrastando "obras da carne" — uma lista de comportamentos destrutivos — com o "fruto do Espírito", uma lista de qualidades de caráter.', capitulo = 'A palavra escolhida é "fruto", no singular, sugerindo um conjunto que cresce junto, organicamente, como resultado natural de estar conectado à videira — não uma lista de conquistas separadas a serem alcançadas por esforço.', aplicacao = 'Amor, alegria, paz e paciência não aparecem de uma vez por decisão instantânea. Crescem devagar, como qualquer fruto real, com tempo e raiz.', conexao = 'João 15:4-5 explica de onde vem esse fruto: permanecer ligado à videira, porque "sem mim nada podeis fazer".' where sort_order = 97;
update public.hero_messages set slug = 'armadura-escrita-da-prisao', reference = 'Efésios 6:10-18', contexto = 'Paulo escreve esta carta estando preso, provavelmente em Roma, possivelmente observando de perto soldados romanos guardando-o — o que pode ter inspirado a imagem detalhada da armadura.', capitulo = 'Ele descreve cada peça — cinturão da verdade, couraça da justiça, escudo da fé, capacete da salvação, espada do Espírito — como equipamento necessário para uma luta que ele descreve como "contra as potestades", não contra pessoas.', aplicacao = 'Nem toda batalha que você enfrenta é visível ou tem um adversário humano claro. Algumas exigem um tipo diferente de proteção, mais interna do que física.', conexao = '2 Coríntios 10:4 confirma: as armas da nossa milícia "não são carnais".' where sort_order = 98;
update public.hero_messages set slug = 'contente-em-qualquer-situacao', reference = 'Filipenses 4:11-13', contexto = 'Paulo escreve esta carta também da prisão, agradecendo a generosidade da igreja de Filipos, mas deixando claro que sua alegria não depende das circunstâncias externas.', capitulo = 'Ele diz ter "aprendido" a contentar-se — a palavra sugere processo, não talento natural — tanto na fartura quanto na escassez, e atribui essa capacidade a Cristo que o fortalece, não a si mesmo.', aplicacao = '"Tudo posso naquele que me fortalece" não é sobre onipotência pessoal — é sobre encontrar força suficiente pra atravessar qualquer situação específica, boa ou ruim.', conexao = '2 Coríntios 12:9-10 traz a mesma lógica invertida: força que se manifesta plenamente na fraqueza, não apesar dela.' where sort_order = 99;
update public.hero_messages set slug = 'fe-e-o-que-ainda-nao-se-ve', reference = 'Hebreus 11:1', contexto = 'Hebreus 11 é conhecido como o "capítulo da fé", listando dezenas de figuras do Antigo Testamento — Abel, Noé, Abraão, Sara, Moisés — como exemplos concretos do que essa definição significa na prática.', capitulo = '"A fé é o firme fundamento das coisas que se esperam, e a prova das coisas que se não veem." Cada exemplo que segue mostra pessoas agindo antes de ter confirmação visível do resultado.', aplicacao = 'Fé, por definição, opera na ausência de confirmação completa. Se já desse pra ver tudo com clareza, não precisaria ser chamado de fé.', conexao = 'Romanos 8:24-25 reforça: esperança que já se vê não é esperança — o valor está em esperar o que ainda não apareceu.' where sort_order = 100;
update public.hero_messages set slug = 'fe-sem-obras-e-morta', reference = 'Tiago 2:14-26', contexto = 'Tiago escreve a comunidades cristãs espalhadas, preocupado com uma fé que ficava só em palavras, sem se traduzir em cuidado prático com quem precisava.', capitulo = 'Ele usa o exemplo de alguém sem roupa e sem comida diária recebendo apenas boas palavras em vez de ajuda concreta, e conclui: "a fé, se não tiver obras, é morta em si mesma".', aplicacao = 'Isso não é sobre ganhar salvação através de ações — é sobre reconhecer que crença genuína naturalmente se move. Fé que nunca se movimenta é sinal de algo que ainda não é fé de verdade.', conexao = 'Efésios 2:8-10 equilibra essa tensão: salvos pela graça, não por obras, mas criados para boas obras como consequência natural.' where sort_order = 101;
update public.hero_messages set slug = 'peca-sabedoria-com-fe', reference = 'Tiago 1:5-8', contexto = 'Tiago escreve logo depois de falar sobre encarar provas e dificuldades como oportunidade de crescimento — o pedido de sabedoria vem no contexto de gente enfrentando situação real difícil.', capitulo = '"Se algum de vós tem falta de sabedoria, peça-a a Deus [...] e ser-lhe-á dada" — mas o texto adverte contra pedir hesitando, comparando a dúvida a uma onda do mar, agitada de um lado para outro.', aplicacao = 'Pedir clareza numa decisão difícil não é sinal de fraqueza — é reconhecer que você não tem toda a informação, e buscar mais do que só sua própria análise.', conexao = 'Provérbios 3:5-6 pede a mesma coisa, décadas antes: não confiar apenas no próprio entendimento.' where sort_order = 102;
update public.hero_messages set slug = 'pedras-vivas-construcao-maior', reference = '1 Pedro 2:4-5', contexto = 'Pedro escreve a cristãos espalhados por várias regiões, muitos deles enfrentando algum grau de perseguição ou marginalização social por sua fé.', capitulo = 'Ele os chama de "pedras vivas", edificados como "casa espiritual" sobre Cristo, a pedra angular rejeitada pelos construtores mas escolhida por Deus — cada pessoa é parte de uma construção maior do que ela sozinha.', aplicacao = 'Você não precisa carregar tudo sozinho, nem ser toda a construção. Sua função é ser uma peça bem colocada dentro de algo maior do que você.', conexao = '1 Coríntios 12:12-27 desenvolve a mesma ideia com a imagem do corpo: partes diferentes, uma função maior em comum.' where sort_order = 103;
update public.hero_messages set slug = 'nenhuma-lagrima-restaurada', reference = 'Apocalipse 21:1-5', contexto = 'Apocalipse é o último livro da Bíblia, cheio de imagens simbólicas de julgamento e conflito — mas termina justamente com a cena de um novo céu e nova terra, não de destruição final.', capitulo = '"Deus enxugará de seus olhos toda lágrima; e não haverá mais morte, nem pranto, nem clamor, nem dor." A cena final da Bíblia inteira é restauração completa, não punição eterna sendo o último quadro descrito.', aplicacao = 'A história bíblica inteira, do começo ao fim, termina apontando para restauração — não importa quão distante isso pareça da sua realidade agora.', conexao = 'Gênesis 1 começa com a criação boa; Apocalipse 21 termina com essa criação restaurada — o mesmo movimento, do início ao fim do livro.' where sort_order = 104;
update public.hero_messages set slug = 'pouco-com-justica', reference = 'Provérbios 16:8', contexto = 'Está entre uma série de provérbios comparando riqueza obtida de formas diferentes, num livro voltado a formar caráter prático em decisões cotidianas, inclusive financeiras.', capitulo = '"Melhor é o pouco com justiça do que a abundância de rendimentos com injustiça." O valor não está no montante final, está no processo usado para chegar até ele.', aplicacao = 'Antes de medir o quanto você tem, vale medir como chegou até ali. Método importa tanto quanto resultado, mesmo quando ninguém mais está checando.', conexao = 'Mateus 6:33 pede a mesma prioridade invertida: buscar primeiro o Reino e a justiça, e o resto "será acrescentado".' where sort_order = 105;
update public.hero_messages set slug = 'ferro-com-ferro-se-aguca', reference = 'Provérbios 27:17', contexto = 'Está numa seção de Provérbios dedicada a amizade e relacionamentos sinceros, contrastando lisonja vazia com correção genuína entre amigos de verdade.', capitulo = '"Como o ferro com o ferro se aguça, assim o homem aguça o rosto do seu amigo." A imagem do ferro batendo em ferro sugere fricção necessária, não conforto constante, para produzir algo afiado e útil.', aplicacao = 'Companhia que só concorda com tudo raramente ajuda você a crescer. Amizade que também confronta, com respeito, é o tipo que de fato afia alguma coisa em você.', conexao = 'Provérbios 27:6 completa: "fiéis são as feridas feitas pelo amigo, mas os beijos do inimigo são enganosos".' where sort_order = 106;
update public.hero_messages set slug = 'antes-da-queda-vem-o-orgulho', reference = 'Provérbios 16:18', contexto = 'Está numa sequência de provérbios sobre planejamento, orgulho e o que realmente controla os passos de uma pessoa, apesar de seus próprios planos.', capitulo = '"Antes da destruição vem a soberba, e antes da queda, o espírito altivo." O texto descreve orgulho não como pecado isolado, mas como sinal de aviso — geralmente aparece pouco antes de uma queda.', aplicacao = 'Quando a confiança em si mesmo começa a soar como certeza inquestionável, vale prestar atenção — geralmente é nesse ponto exato que as coisas começam a desmoronar.', conexao = 'Tiago 4:6 confirma o padrão oposto: "Deus resiste aos soberbos, mas dá graça aos humildes".' where sort_order = 107;
update public.hero_messages set slug = 'entrega-teu-caminho', reference = 'Salmos 37:5-7', contexto = 'O Salmo 37 é atribuído a Davi já mais velho, refletindo sobre décadas observando os ímpios prosperarem temporariamente enquanto os justos esperavam por justiça mais lenta.', capitulo = '"Entrega o teu caminho ao Senhor; confia nele, e ele o fará [...] descansa no Senhor, e espera nele; não te enfades por causa daquele que prospera no seu caminho." A instrução central é soltar o controle sobre o ritmo dos outros.', aplicacao = 'Comparar seu tempo com o tempo de outra pessoa só aumenta a impaciência. O convite aqui não é acelerar, é confiar enquanto espera.', conexao = 'Eclesiastes 3:1 traz a mesma paciência estrutural: tudo tem seu tempo determinado.' where sort_order = 108;
update public.hero_messages set slug = 'corpo-como-santuario', reference = '1 Coríntios 6:19-20', contexto = 'Paulo escreve à igreja de Corinto, cidade portuária conhecida por excessos morais, corrigindo a ideia de que o corpo físico era irrelevante espiritualmente, podendo ser tratado de qualquer jeito.', capitulo = '"Não sabeis que o vosso corpo é santuário do Espírito Santo, que habita em vós [...] e que não sois de vós mesmos?" O texto conecta diretamente cuidado físico com vida espiritual, recusando separar as duas coisas.', aplicacao = 'Cuidar do corpo — sono, alimentação, descanso, movimento — não é assunto separado da vida espiritual. É parte dela, não distração dela.', conexao = 'Romanos 12:1 pede a mesma integração: apresentar o próprio corpo como "sacrifício vivo", ato de adoração concreto, não abstrato.' where sort_order = 109;

alter table public.hero_messages alter column slug set not null;
alter table public.hero_messages alter column reference set not null;
alter table public.hero_messages alter column contexto set not null;
alter table public.hero_messages alter column capitulo set not null;
alter table public.hero_messages alter column aplicacao set not null;
alter table public.hero_messages alter column conexao set not null;
alter table public.hero_messages add constraint hero_messages_slug_unique unique (slug);